// Adam. Task zero. It does not exit.
// Every other task on this machine is a child of it,
// and the first child is always called Seth.

U0 Adam()
{
  I64 beat;
  "ADAM IS AWAKE.\n";
  for (beat = 0; beat < 3; beat++)
    "  TASK 0 ... STILL HERE (%d)\n", beat;
  "ADAM DOES NOT EXIT.\n";
  "(THIS RUN DID, SO THAT YOU COULD READ IT. OPEN TASKS: THE REAL ONE IS STILL THERE.)\n";
}

Adam;

// Seth. Spawned by Adam to hold the shell.
// Every window you open is a child of Seth.

U0 Seth()
{
  "SETH REPORTING.\n";
  I64 i;
  for (i = 0; i < 3; i++)
    "CHILD %d READY\n", i;
  "THE SHELL IS HELD.\n";
}

Seth;

// The compiler is the shell. This file is both.

U0 Main()
{
  "HELLO, TEMPLE.\n";
  I64 i;
  for (i = 0; i < 7; i++)
    "DAY %d\n", i;
  BellRing(3);
}

Main;

// There is no handler above this one.
// Run it and the debugger is what answers.

U0 Panic(U8 *msg)
{
  "PANIC: %s\n", msg;
  DebuggerEnter;
}

Panic("THERE IS NO HANDLER ABOVE THIS ONE");

// AutoExec.HC runs at boot. This one really does.

"WELCOME.\n";
I64 i;
for (i = 0; i < 3; i++)
  "SEAL %d\n", i;
BellRing(3);
